      g.moveTo(w / 2, 150);
      g.lineTo(w - 230, h / 2);
      g.lineTo(w / 2, h - 150);
      g.lineTo(230, h / 2);
      g.closePath();
      g.fill();
      g.fillStyle = "#d9b26a";
      g.beginPath();
