      g.lineTo(w / 2, h - 230);
      g.lineTo(330, h / 2);
      g.closePath();
      g.fill();
      g.fillStyle = "#8c1c1c";
      g.beginPath();
      g.arc(w / 2, h / 2, 70, 0, TAU);
