  var V = (x, y, z) => new Vector3(x, y, z);
  function createDSL(director2) {
    const shots = [];
    const cues = [];
    const api = {
      shots,
      cues,
      S(t0, fn) {
        if (!Number.isFinite(t0)) console.error("bad shot time", t0, fn.toString().slice(0, 80));
        shots.push({ t0, fn });
      },
      whip(t, dir = [1, 0], len = 0.16) {
        director2.transitions.push({ t, kind: "whip", len, dir });
        cues.push({ t: t - 0.12, name: "whoosh", p: { gain: 0.5 } });
      },
      flash(t, len = 0.6, color = [1, 1, 1], amount = 1) {
        director2.transitions.push({ t, kind: "flash", len, color, amount });
      },
      dip(t, len = 0.35) {
        director2.transitions.push({ t, kind: "dip", len });
      },
      zoom(t, len = 0.25) {
        director2.transitions.push({ t, kind: "zoom", len });
      },
      cue(t, name, p = {}) {
        if (Number.isFinite(t)) cues.push({ t, name, p });
      }
    };
    return api;
  }
