  function depthOverlay(c, label, from, to, p) {
    const g = c.use2D();
    const a = c.project(from), b = c.project(to);
    if (a.behind || b.behind) return;
    const k = ease.outCubic(p / 0.8);
    const yb = a.y + (b.y - a.y) * k;
    g.save();
    g.strokeStyle = "rgba(255,255,255,0.85)";
    g.lineWidth = 3;
    g.setLineDash([12, 10]);
    g.beginPath();
    g.moveTo(a.x, a.y);
    g.lineTo(a.x + (b.x - a.x) * k, yb);
    g.stroke();
    g.setLineDash([]);
    g.fillStyle = "#ff6a3a";
    g.beginPath();
    g.arc(a.x + (b.x - a.x) * k, yb, 9, 0, Math.PI * 2);
    g.fill();
    g.restore();
    revealText(g, label, a.x + 40, (a.y + yb) / 2, { family: FONT.title, size: 110, color: "#fff", p: p - 0.4, align: "left", shadow: { color: "rgba(0,0,0,0.6)", blur: 20 } });
  }
